#[derive(Default, PartialEq, Debug, Clone)]
pub struct UseCase {
    abbreviation: Option<String>,
    description: Option<String>,
    extended_description: Option<String>,
    extended_title: Option<String>,
    inputs: Vec<UseCaseInputPair>,
    module: UseCaseModule,
    name: String,
    subtitle: Option<String>,
    ty: UseCaseTy,
}

impl UseCase {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsUseCase<'a>> {
        use crate::types::generated::usecase_generated::UseCaseBuilder as FbsUseCaseBuilder;

        let abbreviation_offset = self.abbreviation.as_ref().map(|s| builder.create_string(s));
        let description_offset = self.description.as_ref().map(|s| builder.create_string(s));
        let extended_description_offset = self.extended_description.as_ref().map(|s| builder.create_string(s));
        let extended_title_offset = self.extended_title.as_ref().map(|s| builder.create_string(s));
        let mut inputs_offsets = Vec::with_capacity(self.inputs.len());
        for val in self.inputs.iter() {
            let offset = val.serialize_to(builder);
            inputs_offsets.push(offset);
        }
        let inputs_offset = builder.create_vector(&inputs_offsets);
        let name_offset = builder.create_string(&self.name);
        let subtitle_offset = self.subtitle.as_ref().map(|s| builder.create_string(s));

        let mut bldr = FbsUseCaseBuilder::new(builder);
        if let Some(offset) = abbreviation_offset {
            bldr.add_abbreviation(offset);
        }
        if let Some(offset) = description_offset {
            bldr.add_description(offset);
        }
        if let Some(offset) = extended_description_offset {
            bldr.add_extended_description(offset);
        }
        if let Some(offset) = extended_title_offset {
            bldr.add_extended_title(offset);
        }
        bldr.add_inputs(inputs_offset);
        bldr.add_module(FbsUseCaseModule::from(self.module));
        bldr.add_name(name_offset);
        if let Some(offset) = subtitle_offset {
            bldr.add_subtitle(offset);
        }
        bldr.add_ty(FbsUseCaseTy::from(self.ty));
        bldr.finish()
    }
}

impl From<FbsUseCase<'_>> for UseCase {
    fn from(fbs: FbsUseCase<'_>) -> Self {
        let abbreviation = fbs.abbreviation().map(ToOwned::to_owned);
        let description = fbs.description().map(ToOwned::to_owned);
        let extended_description = fbs.extended_description().map(ToOwned::to_owned);
        let extended_title = fbs.extended_title().map(ToOwned::to_owned);
        let mut inputs = Vec::new();
        for elem in fbs.inputs() {
            inputs.push(elem.into());
        }

        let module = UseCaseModule::from(fbs.module());
        let name = fbs.name().to_owned();
        let subtitle = fbs.subtitle().map(ToOwned::to_owned);
        let ty = UseCaseTy::from(fbs.ty());
        Self {
            abbreviation,
            description,
            extended_description,
            extended_title,
            inputs,
            module,
            name,
            subtitle,
            ty,
        }
    }
}

